#!/usr/bin/env node
'use strict';
// The acceptance gate. Design rules, in order of importance:
//
// 1. RE-RUN, don't read. Every report consumed here is regenerated by
//    invoking its producer checker fresh (with --no-write, so acceptance
//    never mutates the project it's auditing), then schema-validated. A
//    stale, hand-edited, or repo-planted report JSON can never satisfy
//    this gate.
// 2. REGISTRY-DRIVEN. The set of producers comes from registry.json, not a
//    hardcoded list — a new skill registered with acceptanceGated: true
//    cannot be forgotten here (v0.4 forgot backend entirely).
// 3. FAIL CLOSED. Producer missing => not_evaluated (caps at CONDITIONAL).
//    Producer crashed, hung past its timeout, or emitted invalid output
//    => fail (BLOCK).
// 4. BUILDER != ACCEPTOR. Without --acceptor-context separate, the verdict
//    is capped at CONDITIONAL: the context that built cannot self-SHIP.
//
// Usage: node accept-check.js --root <dir> --acceptor-context separate|same
//        [--runtime-verified]
//        [--strict] [--out <file>] [--no-write]

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');
const { corePaths } = require('./resolve-core.cjs');
const core = corePaths();
const { parseArgs } = require(path.join(core.lib, 'args.cjs'));
const { classify, conditionMet } = require(path.join(core.lib, 'classify.cjs'));
const { readText, sectionHasContent, check, runCli, computeVerdict } = require(path.join(core.lib, 'report.cjs'));
const { validate } = require(path.join(core.lib, 'schema.cjs'));
const registry = require(core.registry);

const PRODUCER_TIMEOUT_MS = 60_000;

function checkDocumentArtifact(root, artifact, checks) {
  const p = path.join(root, artifact.file);
  if (!fs.existsSync(p)) {
    checks.push(check(`A-${artifact.id}`, 'fail', `required document ${artifact.file} is missing`));
    return;
  }
  const text = readText(p);
  const missing = (artifact.requiredHeadings || []).filter((h) => !sectionHasContent(text, h));
  checks.push(missing.length > 0
    ? check(`A-${artifact.id}`, 'fail', `${artifact.file} missing heading(s): ${missing.join(', ')}`)
    : check(`A-${artifact.id}`, 'pass', `${artifact.file}${provenanceSuffix(text)}`));
}

// A document reconstructed from the implementation cannot be evidence about
// the implementation — it records what the code does, not what it should do,
// and it will agree with the code every time because it was read off it.
//
// Declared as a line in the document: `Provenance: stated-by-human` /
// `derived-from-session` / `reconstructed-from-code`. Undeclared is treated
// as unknown, not as human — assuming the safer value is how a reconstructed
// contract would pass as intent.
const PROVENANCE_RE = /^\s*(?:>\s*)?(?:\*\*)?provenance(?:\*\*)?\s*[:—-]\s*([a-z-]+)/im;
const HUMAN_ANCHORED = new Set(['stated-by-human', 'human', 'authored-by-human']);

function provenanceOf(text) {
  const match = PROVENANCE_RE.exec(text);
  return match ? match[1].toLowerCase() : 'undeclared';
}

function provenanceSuffix(text) {
  const value = provenanceOf(text);
  return value === 'undeclared' ? ' (provenance undeclared)' : ` (provenance: ${value})`;
}

// Compares the producer skill's install-marker version against this skill's
// own — catches a stale/mixed-version vendor after a partial suite upgrade,
// or a same-named-but-foreign directory impersonating a sibling skill. In a
// dev checkout (no markers at all) this is a no-op: nothing to compare, so
// nothing is flagged.
function readMarkerVersion(skillDir) {
  const p = path.join(skillDir, '.agent-skills-install.json');
  if (!fs.existsSync(p)) return null;
  try {
    return JSON.parse(readText(p)).version || null;
  } catch {
'use strict';
// Locates the suite core. Duplicated verbatim in every skill's scripts/ BY
// DESIGN: it is the one file that cannot itself live in the core, and it
// keeps each skill standalone after install (the installer vendors core/lib,
// core/schemas, and registry.json into scripts/vendor/).
const fs = require('fs');
const path = require('path');

function corePaths() {
  // Vendor first: it was pinned at install time by THIS skill's own
  // install.mjs run, so it's the version this skill was actually shipped
  // with. Preferring an ambient ../../core (a sibling suite checkout, or an
  // older/different install sharing the same skills directory) would run
  // this skill's checker logic against a core it was never tested with —
  // silently, since both candidates satisfy the same existence check.
  const candidates = [
    { core: path.join(__dirname, 'vendor'), registry: path.join(__dirname, 'vendor', 'registry.json') },
    { core: path.resolve(__dirname, '..', '..', 'core'), registry: path.resolve(__dirname, '..', '..', 'registry.json') },
  ];
  for (const c of candidates) {
    if (fs.existsSync(path.join(c.core, 'lib', 'report.cjs')) && fs.existsSync(c.registry)) {
      return { lib: path.join(c.core, 'lib'), schemas: path.join(c.core, 'schemas'), registry: c.registry, suiteRoot: path.resolve(__dirname, '..', '..') };
    }
  }
  throw new Error(
    'agent-skills core not found. Install skills with scripts/install.mjs (which vendors the core), or run from the suite checkout.'
  );
}

module.exports = { corePaths };
